when.set-body:
@{
            var body = context.Response.Body.As<string>(preserveContent: true);
            if (string.IsNullOrWhiteSpace(body))
            {
                return body;
            }

            var j = Newtonsoft.Json.Linq.JObject.Parse(body);
            var baseUrl = context.Request.OriginalUrl.Scheme + "://" + context.Request.OriginalUrl.Host + "/" + context.Api.Path.Trim('/') + "/";
            var cardUrl = baseUrl + "agent-card.json";

            // APIM A2A schema can expose either "url" or "agentCardUrl" depending on source/version.
            j["url"] = cardUrl;
            j["agentCardUrl"] = cardUrl;

            var interfaces = j["supportedInterfaces"] as Newtonsoft.Json.Linq.JArray;
            if (interfaces != null)
            {
                foreach (var item in interfaces.OfType<Newtonsoft.Json.Linq.JObject>())
                {
                    item["url"] = baseUrl;
                }
            }

            return j.ToString(Newtonsoft.Json.Formatting.None);
        }
